'use strict';
(function(root){
const clone=x=>JSON.parse(JSON.stringify(x));
function prediction(result,order,cast=null){const log=result.logs.find(l=>l.order===order);if(!log?.damage)throw Error('照合する攻撃を選んでください');const d=cast==null?log.damage:log.damage.casts?.[cast];if(!d)throw Error('照合する詠唱がありません');return {order,cast,actor:log.actor,skill:log.skill,name:log.name,turn:log.turn,min:d.min,max:d.max,params:clone(d.params||{}),factors:clone(d.factors||{}),buffs:clone(log.buffsBefore||[]),referenceOnly:!!log.damage.referenceOnly,conditional:!!(log.damage.conditional||log.aiControlled)};}
function compare(predicted,observations){if(!Array.isArray(observations)||!observations.length||observations.length>100||observations.some(n=>!Number.isSafeInteger(n)||n<0||n>1e10))throw Error('観測値は0以上の整数を1〜100件で指定してください');const midpoint=(predicted.min+predicted.max)/2,mean=observations.reduce((a,b)=>a+b,0)/observations.length;return {mean,count:observations.length,midpoint,difference:mean-midpoint,differencePercent:midpoint?(mean/midpoint-1)*100:null,outside:observations.filter(n=>n<predicted.min||n>predicted.max).length,minObserved:Math.min(...observations),maxObserved:Math.max(...observations)};}
function create({result,configuration,profile,order,cast=null,observations,kind,note=''}){if(!['measured','expectation'].includes(kind))throw Error('実測か期待値かを指定してください');if(String(note).length>500)throw Error('メモは500文字以内です');const predicted=prediction(result,order,cast);return {schema:1,created:new Date().toISOString(),model:'0.38',kind,note:String(note),observations:[...observations],comparison:compare(predicted,observations),predicted,configuration:clone(configuration),profile:clone(profile)};}
function recompute(record,master){if(record.schema!==1)throw Error('照合記録の形式が未対応です');const result=root.SequenceEngine.simulate(record.configuration,master,record.profile),predicted=prediction(result,record.predicted.order,record.predicted.cast);return {predicted,comparison:compare(predicted,record.observations)};}
root.Measurement36={prediction,compare,create,recompute};
})(typeof window==='undefined'?globalThis:window);
